import json,os,shutil
from pathlib import Path
import psutil
r={"ram_available":psutil.virtual_memory().available,"cpu_count":os.cpu_count(),"disk_available":shutil.disk_usage("/kaggle/working").free}
Path("/kaggle/working/runtime_resources.json").write_text(json.dumps(r));print(json.dumps(r),flush=True)
assert r["ram_available"]>12*1024**3 and r["disk_available"]>12*1024**3,"runtime capacity insufficient"
import base64,hashlib,runpy,sys
os.chdir("/kaggle/working");sys.path.insert(0,"/kaggle/working")
P={'mix_model.py': {'base64': '', 'sha256': '8c5a369ea5f89b7534dea45003b4a076eb0e58adfc3c84b207492cd495ac8540'}, 'pool_adapter.py': {'base64': '', 'sha256': '63e29813b955e42319e0a11e79311429d566a68f35132dd5b850e2e63185334d'}, 'split_rule.py': {'base64': '', 'sha256': '874dac28771e99e93c6f8a4f4633da5090ccd3d63b30a6c063231f015beb9a42'}, 'params.json': {'base64': '', 'sha256': 'a0e3745b0666feab8ad47dfc508f162d78edc4036736858f6a7e8b224c574fab'}}
for name,item in P.items():
 b=base64.b64decode(item["base64"]);assert hashlib.sha256(b).hexdigest()==item["sha256"];Path(name).write_bytes(b)
runpy.run_path("mix_model.py",run_name="__main__")
